@startuml

class Home {
  + Name : string
}

class Department {
  + Name : string
}

class Room {
  + RoomNumber : int
}

class Bed {
  + BedNumber : int
  + Category : string
}

class StayCategory {
  + Type : string
  + Price : double
}

class Inhabitant {
  + Name : string
  + RegistrationDate : date
}

class AssessmentResult {
  + NeedsHelpForEating : boolean
  + NeedsHelpForDressing : boolean
  + NeedsPersonalCare : boolean
}

class WaitingList {
  + Position : int
}

class Proposal {
  + Date : date
  + Accepted : boolean
}

class Invoice {
  + InvoiceNumber : int
  + OutstandingAmount : double
  + Paid : boolean
}

class PaymentEvent {}

Home "1" -- "*" Department
Department "1" -- "*" Room
Room "1" -- "*" Bed
StayCategory "1" -- "*" Inhabitant
Inhabitant "1" -- "*" AssessmentResult
AssessmentResult "1" -- "*" StayCategory
Inhabitant "0..*" -- "*" WaitingList
WaitingList "0..*" -- "*" Proposal
Proposal "1" -- "1" Inhabitant
Invoice "1" -- "1" Inhabitant
Inhabitant "0..*" -- "0..*" Invoice
Invoice "1" -- "0..*" PaymentEvent

@enduml

